WITH with_dims AS (SELECT e.id, e.customer_id, e.store_id, e.status, e.amount, e.discount, c.city, c.country, c.email FROM orders e LEFT JOIN customers c ON e.customer_id = c.id) SELECT CASE WHEN discount >= 0.38 THEN 'LARGE' ELSE 'SMALL' END AS discount_tier, country, SUM(discount) FILTER (WHERE status = 'SHIPPED') AS shipped_total_discount, ROUND(AVG(amount), 2) AS avg_amount, COUNT(*) FILTER (WHERE city = 'Berlin') AS berlin_rows, SORT_ARRAY(COLLECT_SET(city)) AS city_list, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, GROUPING(CASE WHEN discount >= 0.38 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_level FROM with_dims GROUP BY GROUPING SETS ((CASE WHEN discount >= 0.38 THEN 'LARGE' ELSE 'SMALL' END, country), (CASE WHEN discount >= 0.38 THEN 'LARGE' ELSE 'SMALL' END)) ORDER BY discount_tier
